create table xxcus.xxcmp_screenings (
    screening_id          number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    case_id               number not null enable,
    party_id              number not null enable,
    screening_type        varchar2(30 byte) not null enable,
    match_status          varchar2(30 byte) default 'NO_MATCH' not null enable,
    pep_flag              varchar2(1 byte) default 'N' not null enable,
    sanctions_flag        varchar2(1 byte) default 'N' not null enable,
    adverse_media_flag    varchar2(1 byte) default 'N' not null enable,
    capture_method        varchar2(30 byte) default 'MANUAL' not null enable,
    source_reference      varchar2(1000 byte),
    result_notes          varchar2(4000 byte),
    screened_date         date default trunc(sysdate) not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_screenings
    add constraint xxcmp_screenings_ck1
        check ( screening_type in ( 'REGISTRY', 'SANCTIONS', 'PEP', 'ADVERSE_MEDIA' ) ) enable;

alter table xxcus.xxcmp_screenings
    add constraint xxcmp_screenings_ck2
        check ( match_status in ( 'NO_MATCH', 'POTENTIAL_MATCH', 'CONFIRMED_MATCH', 'FALSE_POSITIVE' ) ) enable;

alter table xxcus.xxcmp_screenings
    add constraint xxcmp_screenings_ck3
        check ( pep_flag in ( 'Y', 'N' )
                and sanctions_flag in ( 'Y', 'N' )
                and adverse_media_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_screenings
    add constraint xxcmp_screenings_ck4
        check ( capture_method in ( 'MANUAL', 'API' ) ) enable;

alter table xxcus.xxcmp_screenings
    add constraint xxcmp_screenings_pk primary key ( screening_id )
        using index enable;


